  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-border: rgba(148, 163, 184, 0.2);
      --text: #e5eefc;
      --muted: #9fb2d1;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --accent-soft: rgba(96, 165, 250, 0.16);
      --success: #34d399;
      --choice-bg: rgba(15, 23, 42, 0.95);
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.25), transparent 28%),
        linear-gradient(180deg, #111827 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .quiz-card {
      width: min(100%, 760px);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      box-shadow: var(--shadow);
      padding: 32px;
      backdrop-filter: blur(16px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.9rem, 3vw, 2.5rem);
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      background: rgba(15, 23, 42, 0.72);
      border: 1px solid rgba(148, 163, 184, 0.14);
      border-radius: 16px;
      padding: 20px;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-width: 0;
    }

    legend {
      padding: 0;
      font-size: 1.08rem;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.96rem;
      line-height: 1.5;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      border-radius: 12px;
      border: 1px solid rgba(148, 163, 184, 0.16);
      background: var(--choice-bg);
      cursor: pointer;
      transition: border-color 0.2s ease, transform 0.2s ease, background-color 0.2s ease;
    }

    .choice:hover,
    .choice:focus-within {
      border-color: rgba(96, 165, 250, 0.65);
      background: var(--accent-soft);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 18px;
      height: 18px;
      accent-color: var(--accent-strong);
      flex: none;
    }

    .choice-text {
      line-height: 1.4;
    }

    button {
      border: 0;
      border-radius: 12px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: #eff6ff;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      cursor: pointer;
      transition: transform 0.2s ease, filter 0.2s ease;
    }

    button:hover,
    button:focus-visible {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    .result {
      min-height: 1.5em;
      margin: 4px 0 0;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      .quiz-card {
        padding: 24px;
      }
    }
  </style>
</head>
