            <label class="choice">
              <input type="checkbox" name="q1" value="Python">
              <span class="choice-text">Python</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="HTML">
              <span class="choice-text">HTML</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="Ruby">
              <span class="choice-text">Ruby</span>
            </label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which languages are generally considered low-level or systems-focused?</legend>
          <div class="choices">
            <label class="choice">
              <input type="checkbox" name="q2" value="C">
              <span class="choice-text">C</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="Rust">
              <span class="choice-text">Rust</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="Assembly">
              <span class="choice-text">Assembly</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="SQL">
              <span class="choice-text">SQL</span>
            </label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which of these languages are strongly associated with the Java Virtual Machine?</legend>
          <div class="choices">
            <label class="choice">
              <input type="checkbox" name="q3" value="Java">
              <span class="choice-text">Java</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Kotlin">
              <span class="choice-text">Kotlin</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Scala">
              <span class="choice-text">Scala</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Go">
              <span class="choice-text">Go</span>
            </label>
          </div>
        </fieldset>
      </div>

      <button type="submit">Submit Quiz</button>
      <p id="result" class="result" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
